-- Raw landing tables for the collection workflow (generated by make_messy.py).
-- Every source column is text so messy values (R$ 81,16 / -3 / 3x / mixed dates) never fail an insert.
-- API tables also keep the untouched record in raw_record, because some records have renamed or
-- missing keys. Typing and fixing happen in the cleaning workflow. Run once in the Supabase SQL editor.

create schema if not exists raw;

create table if not exists raw.orders_csv (
    order_id                           text,
    customer_id                        text,
    order_status                       text,
    order_purchase_timestamp           text,
    order_approved_at                  text,
    order_delivered_carrier_date       text,
    order_delivered_customer_date      text,
    order_estimated_delivery_date      text,
    _run_id                            text,
    _loaded_at                         timestamptz default now()
);

create table if not exists raw.order_items_csv (
    order_id                           text,
    order_item_id                      text,
    product_id                         text,
    seller_id                          text,
    shipping_limit_date                text,
    price                              text,
    freight_value                      text,
    _run_id                            text,
    _loaded_at                         timestamptz default now()
);

create table if not exists raw.customers_csv (
    customer_id                        text,
    customer_unique_id                 text,
    customer_zip_code_prefix           text,
    customer_city                      text,
    customer_state                     text,
    _run_id                            text,
    _loaded_at                         timestamptz default now()
);

create table if not exists raw.sellers_csv (
    seller_id                          text,
    seller_zip_code_prefix             text,
    seller_city                        text,
    seller_state                       text,
    _run_id                            text,
    _loaded_at                         timestamptz default now()
);

create table if not exists raw.geolocation_csv (
    geolocation_zip_code_prefix        text,
    geolocation_lat                    text,
    geolocation_lng                    text,
    geolocation_city                   text,
    geolocation_state                  text,
    _run_id                            text,
    _loaded_at                         timestamptz default now()
);

create table if not exists raw.products_sheet (
    product_id                         text,
    product_category_name              text,
    product_name_lenght                text,
    product_description_lenght         text,
    product_photos_qty                 text,
    product_weight_g                   text,
    product_length_cm                  text,
    product_height_cm                  text,
    product_width_cm                   text,
    _run_id                            text,
    _loaded_at                         timestamptz default now()
);

create table if not exists raw.category_translation_sheet (
    product_category_name              text,
    product_category_name_english      text,
    _run_id                            text,
    _loaded_at                         timestamptz default now()
);

create table if not exists raw.payments_api (
    order_id                           text,
    payment_sequential                 text,
    payment_type                       text,
    payment_installments               text,
    payment_value                      text,
    raw_record                         jsonb,
    _run_id                            text,
    _loaded_at                         timestamptz default now()
);

create table if not exists raw.reviews_api (
    review_id                          text,
    order_id                           text,
    review_score                       text,
    review_comment_title               text,
    review_comment_message             text,
    review_creation_date               text,
    review_answer_timestamp            text,
    raw_record                         jsonb,
    _run_id                            text,
    _loaded_at                         timestamptz default now()
);
